window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-073f6c4e3c2aead4"]={"versions": [{"id": "FIG-073f6c4e3c2aead4", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm (Strukturdiagramm / Architekturebene).</li>\n<li><strong>Architektonische Einordnung:</strong> Darstellung des funktionalen Spektrums der AUTOSAR Adaptive Platform (AP) innerhalb der Domänen-Kategorie <em>Storage</em> gemäß <code>AUTOSAR_AP_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Definition und formale Zuordnung des Functional Clusters (FC) <code>Persistency</code> (<code>ara::per</code>) als zentrale Plattforminstanz für nicht-flüchtige Datenspeicherung (Non-Volatile Data Management) auf POSIX-basierten Adaptive-ECUs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten & Stereotypen:</strong></li>\n<li><code>Persistency</code>: Spezifiziert als <code>«aapFunctionalCluster»</code> (AUTOSAR Adaptive Platform Functional Cluster). Bildet die alleinige Entität der Kategorie <em>Storage</em>.</li>\n<li><strong>Schnittstellen & Namensräume (C++ API):</strong></li>\n<li><strong><code>ara::per::KeyValueStorage</code>:</strong> Typsicherer Zugriff auf strukturierte Schlüssel-Wert-Paare (skalare Typen, Arrays, komplexe Datenobjekte) mit integrierter Serialisierung/Deserialisierung.</li>\n<li><strong><code>ara::per::FileStorage</code>:</strong> Unstrukturierter blockorientierter Stream-Zugriff über Reader-/Writer-Accessoren (<code>ReadAccessor</code>, <code>ReadWriteAccessor</code>) auf partitionierte Dateistrukturen.</li>\n<li><strong>Plattformbeziehungen & OS-Bindung:</strong></li>\n<li>Kapselt die darunterliegenden POSIX-Dateisystemtreiber (z. B. ext4, Flash-Dateisysteme) und NVRAM-Hardwaretreiber gegenüber Adaptive Applications (AA).</li>\n<li>Logische Kopplung an <em>Update and Configuration Management</em> (UCM) zur Unterstützung konsistenter Daten- und Schemamigrationen bei Software-Updates.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Statischer Charakter:</strong> Das Diagramm modelliert die Klassenzugehörigkeit; kein dynamischer Sequenzablauf im Schaubild enthalten.</li>\n<li><strong>Laufzeit- und Ausführungsmodell:</strong></li>\n<li><strong>Bibliotheksmodell:</strong> Typischerweise als In-Process-Library realisiert; Methodenaufrufe von <code>ara::per</code> laufen direkt im Thread-Kontext der aufrufenden Adaptive Application.</li>\n<li><strong>Synchronisation & Atomizität:</strong> Datei- und Key-Value-Modifikationen erfolgen standardmäßig im Cache/Puffer; die persistente Sicherung wird über explizite Synchronisationsaufrufe (z. B. <code>SyncToStorage()</code>) transaktional und atomar gegen Stromausfall abgesichert.</li>\n<li><strong>Fehlerpfade:</strong> Rückgabe über <code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code> ohne C++-Exceptions.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration (ARXML):</strong></li>\n<li>Zugriff auf Persistency-Ressourcen muss im Execution- und Service-Instance-Manifest explizit deklariert werden (<code>PersistencyPortPrototype</code>, <code>PersistencyFileProxyInterface</code>, <code>PersistencyKeyValueDatabaseInterface</code>).</li>\n<li>Deklarative Definition von Quotas (<code>maxAllowedSize</code>), Redundanzstufen (z. B. CRC32, M-aus-N-Redundanz) sowie Verschlüsselungsparametern (unter Einbindung des Crypto-Stacks).</li>\n<li><strong>Entwickler-Restriktionen:</strong></li>\n<li>Direkte POSIX-I/O-Aufrufe (<code>open</code>, <code>read</code>, <code>write</code>) auf Persistenzpfade verstoßen gegen die Plattformkonformität; der Zugriff hat zwingend über <code>ara::per</code> zu erfolgen, um Konsistenzprüfungen, automatische Wiederherstellung (Data Corruption Recovery) und Migrationspfade nicht zu kompromittieren.</li>\n<li>Applikationen müssen Persistenz-Zugriffe auf deterministische Ausführungsphasen beschränken, um I/O-Blockaden in echtzeitkritischen Verarbeitungszyklen zu verhindern.</li>\n</ul>"}, {"id": "FIG-790bd877ca871bbe", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm (Strukturdiagramm / Architekturebene).</li>\n<li><strong>Architektonische Einordnung:</strong> Darstellung des funktionalen Spektrums der AUTOSAR Adaptive Platform (AP) innerhalb der Domänen-Kategorie <em>Storage</em> gemäß <code>AUTOSAR_AP_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Definition und formale Zuordnung des Functional Clusters (FC) <code>Persistency</code> (<code>ara::per</code>) als zentrale Plattforminstanz für nicht-flüchtige Datenspeicherung (Non-Volatile Data Management) auf POSIX-basierten Adaptive-ECUs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten & Stereotypen:</strong></li>\n<li><code>Persistency</code>: Spezifiziert als <code>«aapFunctionalCluster»</code> (AUTOSAR Adaptive Platform Functional Cluster). Bildet die alleinige Entität der Kategorie <em>Storage</em>.</li>\n<li><strong>Schnittstellen & Namensräume (C++ API):</strong></li>\n<li><strong><code>ara::per::KeyValueStorage</code>:</strong> Typsicherer Zugriff auf strukturierte Schlüssel-Wert-Paare (skalare Typen, Arrays, komplexe Datenobjekte) mit integrierter Serialisierung/Deserialisierung.</li>\n<li><strong><code>ara::per::FileStorage</code>:</strong> Unstrukturierter blockorientierter Stream-Zugriff über Reader-/Writer-Accessoren (<code>ReadAccessor</code>, <code>ReadWriteAccessor</code>) auf partitionierte Dateistrukturen.</li>\n<li><strong>Plattformbeziehungen & OS-Bindung:</strong></li>\n<li>Kapselt die darunterliegenden POSIX-Dateisystemtreiber (z. B. ext4, Flash-Dateisysteme) und NVRAM-Hardwaretreiber gegenüber Adaptive Applications (AA).</li>\n<li>Logische Kopplung an <em>Update and Configuration Management</em> (UCM) zur Unterstützung konsistenter Daten- und Schemamigrationen bei Software-Updates.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statischer Charakter:</strong> Das Diagramm modelliert die Klassenzugehörigkeit; kein dynamischer Sequenzablauf im Schaubild enthalten.</li>\n<li><strong>Laufzeit- und Ausführungsmodell:</strong></li>\n<li><strong>Bibliotheksmodell:</strong> Typischerweise als In-Process-Library realisiert; Methodenaufrufe von <code>ara::per</code> laufen direkt im Thread-Kontext der aufrufenden Adaptive Application.</li>\n<li><strong>Synchronisation & Atomizität:</strong> Datei- und Key-Value-Modifikationen erfolgen standardmäßig im Cache/Puffer; die persistente Sicherung wird über explizite Synchronisationsaufrufe (z. B. <code>SyncToStorage()</code>) transaktional und atomar gegen Stromausfall abgesichert.</li>\n<li><strong>Fehlerpfade:</strong> Rückgabe über <code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code> ohne C++-Exceptions.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration (ARXML):</strong></li>\n<li>Zugriff auf Persistency-Ressourcen muss im Execution- und Service-Instance-Manifest explizit deklariert werden (<code>PersistencyPortPrototype</code>, <code>PersistencyFileProxyInterface</code>, <code>PersistencyKeyValueDatabaseInterface</code>).</li>\n<li>Deklarative Definition von Quotas (<code>maxAllowedSize</code>), Redundanzstufen (z. B. CRC32, M-aus-N-Redundanz) sowie Verschlüsselungsparametern (unter Einbindung des Crypto-Stacks).</li>\n<li><strong>Entwickler-Restriktionen:</strong></li>\n<li>Direkte POSIX-I/O-Aufrufe (<code>open</code>, <code>read</code>, <code>write</code>) auf Persistenzpfade verstoßen gegen die Plattformkonformität; der Zugriff hat zwingend über <code>ara::per</code> zu erfolgen, um Konsistenzprüfungen, automatische Wiederherstellung (Data Corruption Recovery) und Migrationspfade nicht zu kompromittieren.</li>\n<li>Applikationen müssen Persistenz-Zugriffe auf deterministische Ausführungsphasen beschränken, um I/O-Blockaden in echtzeitkritischen Verarbeitungszyklen zu verhindern.</li>\n</ul>"}, {"id": "FIG-fca17add9d4918c0", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm (Strukturdiagramm / Architekturebene).</li>\n<li><strong>Architektonische Einordnung:</strong> Darstellung des funktionalen Spektrums der AUTOSAR Adaptive Platform (AP) innerhalb der Domänen-Kategorie <em>Storage</em> gemäß <code>AUTOSAR_AP_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Definition und formale Zuordnung der Functional Clusters (FC) der Kategorie <em>Storage</em>. Neben dem lokalen <code>Persistency</code> (<code>ara::per</code>) wird mit <code>Remote Persistency</code> ein daemon-basierter Plattformdienst zur Verwaltung persistenter Daten über Maschinengrenzen hinweg (z. B. Remote Storage, Cloud-Anbindung, stellvertretende Speicherung) spezifiziert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten & Stereotypen:</strong></li>\n<li><code>Persistency</code>: Spezifiziert als <code>«aapFunctionalCluster»</code> (AUTOSAR Adaptive Platform Functional Cluster). Bildet die lokale In-Process-Komponente der Kategorie <em>Storage</em>.</li>\n<li><code>Remote Persistency</code>: Spezifiziert als <code>«aapFunctionalCluster»</code> mit der Eigenschaftsnotation <code>daemon-based</code>. Repräsentiert die dienstorientierte Plattformkomponente für ausgelagerte bzw. verteilte Persistenzdienste.</li>\n<li><strong>Schnittstellen & Namensräume (C++ API):</strong></li>\n<li><strong><code>Persistency</code> (<code>ara::per</code>):</strong> Bietet <code>ara::per::KeyValueStorage</code> (strukturierte Schlüssel-Wert-Speicherung) und <code>ara::per::FileStorage</code> (block- und dateiorientierter Stream-Zugriff via Reader-/Writer-Accessoren).</li>\n<li><strong><code>Remote Persistency</code>:</strong> Service-orientierte Schnittstelle (über <code>ara::com</code>) primär für Key-Value-basierte persistente Datenverwaltung auf entfernten Speichermedien oder zentralen Speicherknoten.</li>\n<li><strong>Plattformbeziehungen & OS-Bindung:</strong></li>\n<li><code>Persistency</code> bindet direkt an lokale POSIX-Dateisysteme bzw. NVRAM-Hardwaretreiber an.</li>\n<li><code>Remote Persistency</code> setzt als Daemon-Prozess auf der Kommunikationsinfrastruktur (<code>ara::com</code>) und dem Netzwerk-Stack auf, um Speicheroperationen prozess- oder maschinenübergreifend an Remote-ECUs oder externe Speicherdienste weiterzuleiten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statischer Charakter:</strong> Das Diagramm modelliert die Komponenten- und Clusterzuordnung; kein expliziter Sequenzablauf enthalten.</li>\n<li><strong>Laufzeit- und Ausführungsmodell:</strong></li>\n<li><strong>Koexistenz zweier Ausführungsmodelle:</strong></li>\n<li><code>Persistency</code>: Bibliotheksmodell (In-Process-Library), ausgeführt im Thread-Kontext der aufrufenden Adaptive Application ohne IPC-Overhead.</li>\n<li><code>Remote Persistency</code>: Explizit <code>daemon-based</code>, ausgeführt als eigenständiger Hintergrundprozess (Daemon) im Adaptive-Betriebssystem.</li>\n<li><strong>Kommunikation & Nebenläufigkeit:</strong> Interaktionen mit <code>Remote Persistency</code> bedingen Inter-Process-Communication (IPC) oder Netzwerkübertragungen (via <code>ara::com</code>), wodurch asynchrone Kommunikationsmuster, Latenzen und Nebenläufigkeitssteuerung über Prozessgrenzen hinweg zum Tragen kommen.</li>\n<li><strong>Synchronisation & Fehlerbehandlung:</strong> Transaktionale Absicherung erfolgt lokal über Sync-Mechanismen (<code>SyncToStorage()</code>), bei <code>Remote Persistency</code> über verteilte Bestätigungspfade und service-orientierte Fehlercodes (<code>ara::core::Result</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Konfiguration (ARXML):</strong></li>\n<li>Für <code>Persistency</code>: Manifestierung lokaler Zugriffe über <code>PersistencyPortPrototype</code> (<code>PersistencyKeyValueDatabaseInterface</code>, <code>PersistencyFileProxyInterface</code>) sowie Definition lokaler Quotas und Redundanzen.</li>\n<li>Für <code>Remote Persistency</code>: Modellierung im Execution-Manifest als separater Prozess (Startup-Konfiguration, Resource-Group) sowie Service-Deployment- und Service-Instance-Manifeste für die Bereitstellung und den Konsum der Remote-Storage-Services via <code>ara::com</code>.</li>\n<li><strong>Entwickler-Restriktionen:</strong></li>\n<li>Architektonische Trennung beachten: Latenzkritische, ECU-lokale Persistenzanforderungen zwingend über <code>ara::per</code> (In-Process) abwickeln; netzwerkweite, geteilte oder Cloud-ausgelagerte Datensätze über <code>Remote Persistency</code> anbinden.</li>\n<li>Bei <code>Remote Persistency</code> müssen Applikationen netzwerkbedingte Latenzen, asynchrone Antwortzeiten und Verbindungsausfälle architektonisch entkoppeln und fehlertolerant behandeln.</li>\n</ul>"}], "trans": [{"from": "FIG-073f6c4e3c2aead4", "to": "FIG-790bd877ca871bbe", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-790bd877ca871bbe", "to": "FIG-fca17add9d4918c0", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Neues Element:</strong> Hinzufügung des Functional Clusters <code>Remote Persistency</code> mit dem Stereotyp <code>«aapFunctionalCluster»</code>.</li>\n<li><strong>Ausführungsmodell:</strong> Kennzeichnung von <code>Remote Persistency</code> mit der Eigenschaft <code>daemon-based</code> (Daemon-basierter Plattformprozess).</li>\n<li><strong>Strukturelle Erweiterung:</strong> Die Domänen-Kategorie <em>Storage</em> umfasst nun zwei Functional Clusters (<code>Persistency</code> und <code>Remote Persistency</code>) statt zuvor ausschließlich <code>Persistency</code>.</li>\n</ul>"}]};
